// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title IoTFirmwareRegistry
 * @notice Manages firmware updates for IoT devices deployed in K8s clusters
 * @dev Firmware blobs are stored off-chain; this contract tracks metadata and update paths
 */
contract IoTFirmwareRegistry is Ownable {
    using ECDSA for bytes32;

    struct FirmwareEntry {
        bytes32 contentHash;
        string storageURI;
        uint256 timestamp;
        address publisher;
        bool active;
    }

    struct DeviceBinding {
        bytes32 currentFirmwareId;
        bytes32 pendingFirmwareId;
        address deviceSigner;
        uint256 lastUpdateBlock;
        bool initialized;
    }

    struct UpdatePath {
        bytes32 sourceFirmwareId;
        bytes32 targetFirmwareId;
        bytes32 deltaHash;
        string deltaURI;
        bool isSymlink;  // If true, deltaURI points to another path's delta
        bytes32 symlinkTarget;  // The path ID this symlinks to
    }

    mapping(bytes32 => FirmwareEntry) public firmwareEntries;
    mapping(bytes32 => DeviceBinding) public deviceBindings;
    mapping(bytes32 => UpdatePath) public updatePaths;
    mapping(bytes32 => bool) public revokedFirmware;
    mapping(address => bool) public authorizedPublishers;

    uint256 public constant MAX_SYMLINK_DEPTH = 8;
    uint256 public updateNonce;

    event FirmwareRegistered(bytes32 indexed firmwareId, address publisher);
    event UpdatePathCreated(bytes32 indexed pathId, bytes32 source, bytes32 target);
    event DeviceUpdated(bytes32 indexed deviceId, bytes32 newFirmwareId);
    event SymlinkCreated(bytes32 indexed pathId, bytes32 symlinkTarget);

    modifier onlyAuthorizedPublisher() {
        require(authorizedPublishers[msg.sender] || msg.sender == owner(), "Not authorized");
        _;
    }

    constructor() Ownable() {
        authorizedPublishers[msg.sender] = true;
    }

    function registerFirmware(
        bytes32 contentHash,
        string calldata storageURI
    ) external onlyAuthorizedPublisher returns (bytes32 firmwareId) {
        firmwareId = keccak256(abi.encodePacked(contentHash, msg.sender, block.timestamp, updateNonce++));
        require(firmwareEntries[firmwareId].timestamp == 0, "Already exists");

        firmwareEntries[firmwareId] = FirmwareEntry({
            contentHash: contentHash,
            storageURI: storageURI,
            timestamp: block.timestamp,
            publisher: msg.sender,
            active: true
        });

        emit FirmwareRegistered(firmwareId, msg.sender);
    }

    function createUpdatePath(
        bytes32 sourceFirmwareId,
        bytes32 targetFirmwareId,
        bytes32 deltaHash,
        string calldata deltaURI
    ) external onlyAuthorizedPublisher returns (bytes32 pathId) {
        require(firmwareEntries[sourceFirmwareId].active, "Source not active");
        require(firmwareEntries[targetFirmwareId].active, "Target not active");
        require(!revokedFirmware[targetFirmwareId], "Target revoked");

        pathId = keccak256(abi.encodePacked(sourceFirmwareId, targetFirmwareId, updateNonce++));

        updatePaths[pathId] = UpdatePath({
            sourceFirmwareId: sourceFirmwareId,
            targetFirmwareId: targetFirmwareId,
            deltaHash: deltaHash,
            deltaURI: deltaURI,
            isSymlink: false,
            symlinkTarget: bytes32(0)
        });

        emit UpdatePathCreated(pathId, sourceFirmwareId, targetFirmwareId);
    }

    function createSymlinkPath(
        bytes32 sourcePathId,
        bytes32 newSourceFirmwareId
    ) external onlyAuthorizedPublisher returns (bytes32 pathId) {
        UpdatePath memory originalPath = updatePaths[sourcePathId];
        require(originalPath.sourceFirmwareId != bytes32(0), "Source path not found");
        require(firmwareEntries[newSourceFirmwareId].active, "New source not active");

        pathId = keccak256(abi.encodePacked(newSourceFirmwareId, originalPath.targetFirmwareId, updateNonce++));

        updatePaths[pathId] = UpdatePath({
            sourceFirmwareId: newSourceFirmwareId,
            targetFirmwareId: originalPath.targetFirmwareId,
            deltaHash: bytes32(0),
            deltaURI: "",
            isSymlink: true,
            symlinkTarget: sourcePathId
        });

        emit SymlinkCreated(pathId, sourcePathId);
    }

    /**
     * @notice Resolves a potentially symlinked update path to get the actual delta info
     * @dev Follows symlink chain up to MAX_SYMLINK_DEPTH; reverts if unresolved
     * @return resolvedPath The final resolved UpdatePath with actual delta data
     */
    function resolveUpdatePath(bytes32 pathId) public view returns (UpdatePath memory resolvedPath) {
        resolvedPath = updatePaths[pathId];
        uint256 depth = 0;

        while (resolvedPath.isSymlink && depth < MAX_SYMLINK_DEPTH) {
            bytes32 nextTarget = resolvedPath.symlinkTarget;
            resolvedPath = updatePaths[nextTarget];
            depth++;
        }

        // If still a symlink after max depth, revert — do not allow unresolved paths
        require(!resolvedPath.isSymlink, "Symlink depth exceeded");
        return resolvedPath;
    }

    /**
     * @notice Apply firmware update to a device after verifying the update path
     * @dev The device must sign the update acceptance; path is resolved through symlinks
     */
    function applyFirmwareUpdate(
        bytes32 deviceId,
        bytes32 pathId,
        bytes calldata deviceSignature
    ) external onlyAuthorizedPublisher {
        DeviceBinding storage device = deviceBindings[deviceId];
        require(device.initialized, "Device not initialized");

        UpdatePath memory resolved = resolveUpdatePath(pathId);

        // Verify the update path starts from device's current firmware
        require(resolved.sourceFirmwareId == device.currentFirmwareId, "Path source mismatch");

        // Verify target firmware is not revoked
        require(!revokedFirmware[resolved.targetFirmwareId], "Target firmware revoked");

        // Verify target firmware is still active
        require(firmwareEntries[resolved.targetFirmwareId].active, "Target firmware not active");

        // Verify device signature over the update acceptance.
        // Bind digest to this contract address and chainId to prevent cross-contract/cross-chain replay.
        bytes32 updateDigest = keccak256(abi.encodePacked(
            block.chainid, address(this), deviceId, resolved.targetFirmwareId, device.lastUpdateBlock
        ));
        address recovered = updateDigest.toEthSignedMessageHash().recover(deviceSignature);
        require(recovered == device.deviceSigner, "Invalid device signature");

        // Apply the update
        device.currentFirmwareId = resolved.targetFirmwareId;
        device.pendingFirmwareId = bytes32(0);
        device.lastUpdateBlock = block.number;

        emit DeviceUpdated(deviceId, resolved.targetFirmwareId);
    }

    function revokeFirmware(bytes32 firmwareId) external onlyOwner {
        revokedFirmware[firmwareId] = true;
        firmwareEntries[firmwareId].active = false;
    }

    function initializeDevice(
        bytes32 deviceId,
        bytes32 initialFirmwareId,
        address deviceSigner
    ) external onlyAuthorizedPublisher {
        require(!deviceBindings[deviceId].initialized, "Already initialized");
        require(firmwareEntries[initialFirmwareId].active, "Firmware not active");

        deviceBindings[deviceId] = DeviceBinding({
            currentFirmwareId: initialFirmwareId,
            pendingFirmwareId: bytes32(0),
            deviceSigner: deviceSigner,
            lastUpdateBlock: block.number,
            initialized: true
        });
    }

    function addPublisher(address publisher) external onlyOwner {
        authorizedPublishers[publisher] = true;
    }

    function removePublisher(address publisher) external onlyOwner {
        authorizedPublishers[publisher] = false;
    }
}
